import{_ as c,l as d,o as a,c as s,v as o,p as l,x as t,d as i,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"阻塞与非阻塞套接字","description":"","frontmatter":{"title":"阻塞与非阻塞套接字","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/socket-nonblock.md","filePath":"cs/socket-nonblock.md","lastUpdated":1789023840000}'),h={name:"cs/socket-nonblock.md"};function E(A,e,m,_,B,f){const r=d("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="阻塞与非阻塞套接字" tabindex="-1">阻塞与非阻塞套接字 <a class="header-anchor" href="#阻塞与非阻塞套接字" aria-label="Permalink to &quot;阻塞与非阻塞套接字&quot;">​</a></h1><div class="epigraph"><p>默认 read 会把进程睡到有字节；非阻塞让调用立即返回「现在没有」，由事件通知再来读。</p><footer>—— 据 Stevens, UNIX Network Programming；Kurose and Ross 对套接字的整理</footer></div><p><a href="/cs/socket-api">上一课</a>把 UDP/TCP 接到文件描述符：<code>connect</code>、<code>accept</code>、<code>read</code>、<code>write</code>。本课不重列调用。缺口是等待：阻塞套接字上，对端慢则线程卡在系统调用里；并发连接若一人一线程，<a href="/cs/thread-shared-addr">进程/线程</a> 成本会先爆。非阻塞加多路复用是同一 API 上的调度合同。网络课在此结束，下一课关系模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Berkeley 套接字默认阻塞：无数据则睡眠，缓冲满则写睡眠。这与<a href="/cs/file-bytestream">文件字节流</a>一致，但网络延迟是对端与路径，不是磁盘臂。服务器要同时服务许多已建立连接，不能为每个 <code>read</code> 配一个内核线程当默认。缺口是<strong>调用是否等待就绪</strong>，不是新的 TCP 状态。</p><p><span class="marginnote"><code>select</code>/<code>poll</code>/<code>epoll</code>/<code>kqueue</code> 都是「等这些描述符可读可写」。本课只钉合同，不选哪一个可移植层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设非阻塞：<code>read</code> 无数据返回 EAGAIN；<code>connect</code> 可在进行中返回。事件循环：注册描述符，醒来后在就绪集合上读写，直到再次 EAGAIN。阻塞套接字仍适合简单客户端。半关闭与 <a href="/cs/tcp-time-wait">TIME_WAIT</a> 不因非阻塞消失。</p>',8)),(a(),l(p,null,{default:t(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLK%5B%22%E9%98%BB%E5%A1%9E%20read%22%5D%20--%3E%20SLEEP%5B%22%E6%97%A0%E6%95%B0%E6%8D%AE%E5%88%99%E7%9D%A1%E7%9C%A0%22%5D%0A%20%20NB%5B%22%E9%9D%9E%E9%98%BB%E5%A1%9E%20read%22%5D%20--%3E%20AGAIN%5B%22%E7%AB%8B%E5%8D%B3%20EAGAIN%22%5D%0A%20%20AGAIN%20--%3E%20MUX%5B%22%E4%BA%8B%E4%BB%B6%E5%A4%9A%E8%B7%AF%E5%86%8D%E8%AF%BB%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>非阻塞把等待从「藏在系统调用里」变成「进程自己调度」，与内核<a href="/cs/timeslice-cfs">时间片</a> 分工：内核仍唤醒，用户决定先服务谁。它不改 TCP 窗口与拥塞；只改线程是否被占住。数据库课即将开始：套接字送来的是字节，还没有表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把异步 I/O 的全部 POSIX 接口写完，不引入用户态协议栈。字节如何变成元组集合，下一课关系模型。</p><p>后课默认：网络端点可以不阻塞线程。持久共享数据需要关系，而不是再开一种套接字。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>阻塞等待就绪；非阻塞立即返回，靠多路复用再来。</li><li>不改变 TCP 语义，只改变进程调度。</li><li>计算机栏下一课进入关系模型。</li><li>出处：Stevens <em>UNIX Network Programming</em>；Kurose and Ross。</li></ul>',7))])}const P=c(h,[["render",E]]);export{k as __pageData,P as default};
